class Solution {
    public int[] nextGreaterElements(int[] nums){
        int n=nums.length;
        int[] answer=new int[n];
        Arrays.fill(answer,-1);
        Deque<Integer> stack=new ArrayDeque<>();
        for(int index=0;index<2*n;index++){
            int current=index%n;
            while(!stack.isEmpty()&&nums[stack.peek()]<nums[current])answer[stack.pop()]=nums[current];
            if(index<n)stack.push(current);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun nextGreaterElements(nums:IntArray):IntArray{
        val answer=IntArray(nums.size){
            -1
        };
        val stack=ArrayDeque<Int>();
        for(index in 0 until 2*nums.size){
            val current=index%nums.size;
            while(stack.isNotEmpty()&&nums[stack.last()]<nums[current])answer[stack.removeLast()]=nums[current];
            if(index<nums.size)stack.addLast(current)
        };
        return answer
    }
}

